const crypto = require('crypto');
const input = $input.first().json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const headers = Object.fromEntries(Object.entries(input.headers || {}).map(([key, value]) => [String(key).toLowerCase(), String(value)]));
const stable = (value) => Array.isArray(value) ? '[' + value.map(stable).join(',') + ']' : value && typeof value === 'object' ? '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stable(value[key])).join(',') + '}' : JSON.stringify(value);
const timestamp = headers['x-snapgad-timestamp'];
const signature = headers['x-snapgad-signature'];
const secret = String($env.SNAPGAD_N8N_SHARED_SECRET || '');
const fail = (message, status) => [{ json: { valid: false, status, error: message } }];
if (!secret || !timestamp || !signature) return fail('Firma requerida.', 401);
if (Math.abs(Date.now() - Number(timestamp) * 1000) > 300000) return fail('Firma vencida.', 401);
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(String(timestamp) + '.' + stable(body)).digest('hex');
const a = Buffer.from(signature); const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('Firma inválida.', 401);
if (!body.jobId || !body.idempotencyKey) return fail('jobId e idempotencyKey son requeridos.', 400);
return [{ json: { valid: true, jobId: String(body.jobId), idempotencyKey: String(body.idempotencyKey) } }];

const crypto = require('crypto');
const input = $input.first().json;
const body = { jobId: input.jobId, idempotencyKey: input.idempotencyKey };
const stable = (value) => Array.isArray(value) ? '[' + value.map(stable).join(',') + ']' : value && typeof value === 'object' ? '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stable(value[key])).join(',') + '}' : JSON.stringify(value);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', String($env.SNAPGAD_N8N_SHARED_SECRET || '')).update(timestamp + '.' + stable(body)).digest('hex');
return [{ json: { ...input, claimBody: body, claimTimestamp: timestamp, claimSignature: signature } }];

const crypto = require('crypto');
const claim = $('Copy — Reclamar Trabajo del Portal').first().json;
const job = claim.body?.job ?? claim.job;
const provider = $input.first().json;
const raw = provider.choices?.[0]?.message?.content ?? provider.body?.choices?.[0]?.message?.content ?? '{}';
let result; try { result = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { throw new Error('COPY_PROVIDER_INVALID_JSON'); }
if (!job || !result?.visualAnalysis || !Array.isArray(result.drafts) || result.drafts.length !== 2) throw new Error('COPY_PROVIDER_INVALID_RESULT');
const body = { jobId: job.id, idempotencyKey: job.idempotencyKey, leaseToken: job.leaseToken, result: { visualAnalysis: result.visualAnalysis, drafts: result.drafts, warnings: Array.isArray(result.warnings) ? result.warnings : [], provider: 'openrouter', model: String($env.OPENROUTER_VISION_MODEL || '') } };
const stable = (value) => Array.isArray(value) ? '[' + value.map(stable).join(',') + ']' : value && typeof value === 'object' ? '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stable(value[key])).join(',') + '}' : JSON.stringify(value);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', String($env.SNAPGAD_N8N_SHARED_SECRET || '')).update(timestamp + '.' + stable(body)).digest('hex');
return [{ json: { completeBody: body, completeTimestamp: timestamp, completeSignature: signature } }];
